import os
import boto3
import json

# Set up AWS credentials via environment variables or AWS configuration
# os.environ["AWS_ACCESS_KEY_ID"] = "your-access-key-id"
# os.environ["AWS_SECRET_ACCESS_KEY"] = "your-secret-access-key"
# os.environ["AWS_DEFAULT_REGION"] = "your-region"

def batch_speech_to_text(file_paths, speaker_diarization=True):
    """
    Requests speaker diarization for a recorded meeting using Amazon Transcribe.

    :param file_paths: List of file paths to audio files.
    :param speaker_diarization: Whether to enable speaker diarization. Default is True.
    :return: List of transcription results.
    """
    # Initialize the Transcribe client
    transcribe_client = boto3.client('transcribe')

    # Prepare the job details
    job_details = []
    for file_path in file_paths:
        job_name = f"meeting-transcription-{len(job_details)}"
        job_details.append({
            "JobName": job_name,
            "Media": {"MediaFileUri": f"s3://{os.environ['AWS_DEFAULT_REGION']}.amazonaws.com/your-bucket-name/{file_path}"},
            "TranscriptionJobSettings": {
                "ContentIdentificationSettings": {
                    "PII": True
                }
            },
            "Settings": {
                "SpeakerDiarizationConfig": {
                    "EnableSpeakerDiarization": speaker_diarization,
                    "MaxSpeakerCount": 10,
                    "MinSpeakerCount": 2
                }
            }
        })

    # Start batch transcription jobs
    for job in job_details:
        transcribe_client.start_transcription_job(**job)

    # Wait for jobs to complete and fetch results
    transcription_results = []
    for job in job_details:
        while True:
            job_status = transcribe_client.get_transcription_job(TranscriptionJobName=job["JobName"])
            if job_status["TranscriptionJob"]["TranscriptionJobStatus"] in ["COMPLETED", "FAILED"]:
                break
        if job_status["TranscriptionJob"]["TranscriptionJobStatus"] == "COMPLETED":
            transcription_results.append(job_status["TranscriptionJob"]["Transcript"]["TranscriptFileUri"])
        else:
            transcription_results.append(None)

    return transcription_results

# Example usage
audio_files = ["meeting1.mp3", "meeting2.mp3"]
results = batch_speech_to_text(audio_files)
for result in results:
    print(result)
